(5919169, 862679, 115444, '<td valign="top">Cool shot</td>', 'Cool shot', '2010-03-27 15:00:19.000000', NULL, 1),
(5919171, 862323, 115444, '<td valign="top">I like the idea you were going for but i think a more front angle would have given you better results</td>', 'I like the idea you were going for but i think a more front angle would have given you better results', '2010-03-27 15:02:18.000000', NULL, 1),
(5919173, 862489, 115444, '<td valign="top">Great shot</td>', 'Great shot', '2010-03-27 15:02:48.000000', NULL, 1),
(5919198, 861979, 38162, '<td valign="top">windy title aside, nice job here.  gl</td>', 'windy title aside, nice job here.  gl', '2010-03-27 15:50:42.000000', NULL, 1),
(5919200, 862343, 38162, '<td valign="top">title detracts from a super concept here.</td>', 'title detracts from a super concept here.', '2010-03-27 16:04:48.000000', NULL, 1),
(5919204, 862529, 38162, '<td valign="top">title detracts from concept.</td>', 'title detracts from concept.', '2010-03-27 16:07:47.000000', NULL, 1),
(5919206, 862565, 38162, '<td valign="top">wow - ready to 10 this one except my eyes got crossed waiting for it to focus.  guess this is meant to be "soft focus" but somehow a tad overdone?  great try.  7</td>', 'wow - ready to 10 this one except my eyes got crossed waiting for it to focus.  guess this is meant to be "soft focus" but somehow a tad overdone?  great try.  7', '2010-03-27 16:10:19.000000', NULL, 1),
(5919283, 862299, 91496, '<td valign="top">Ouch. Do not understand why you want me to look at the bright red border rather than your nice photograph</td>', 'Ouch. Do not understand why you want me to look at the bright red border rather than your nice photograph', '2010-03-27 18:45:27.000000', NULL, 1),
(5919288, 862375, 91496, '<td valign="top">Nice panning.  I really like how the car is facing the viewer but the motion is sideways.  It makes it a special capture.</td>', 'Nice panning.  I really like how the car is facing the viewer but the motion is sideways.  It makes it a special capture.', '2010-03-27 19:01:57.000000', NULL, 1),
(5919290, 862535, 91496, '<td valign="top">Great point of view with an intersting angle.  I like all the reflections.</td>', 'Great point of view with an intersting angle.  I like all the reflections.', '2010-03-27 19:03:54.000000', NULL, 1),
(5919293, 862542, 91496, '<td valign="top">I really like the composition on this one.  The fence sort of has leading parallel lines for the plane motion.  I think a simple square border would have been much better.</td>', 'I really like the composition on this one.  The fence sort of has leading parallel lines for the plane motion.  I think a simple square border would have been much better.', '2010-03-27 19:06:13.000000', NULL, 1),
(5919295, 862078, 91496, '<td valign="top">Very nice how the backdrop is all white. The textures on the blackbird are great.</td>', 'Very nice how the backdrop is all white. The textures on the blackbird are great.', '2010-03-27 19:07:09.000000', NULL, 1),
(5919296, 862671, 91496, '<td valign="top">Great action shot here with the dust trail and all.</td>', 'Great action shot here with the dust trail and all.', '2010-03-27 19:08:22.000000', NULL, 1),
(5919297, 862097, 91496, '<td valign="top">I like how you composed the water tower and the train.  Color is somewhat washed out.  Appears oversharpedn or pizilated in some of the detail areas.</td>', 'I like how you composed the water tower and the train.  Color is somewhat washed out.  Appears oversharpedn or pizilated in some of the detail areas.', '2010-03-27 19:10:06.000000', NULL, 1),
(5919298, 862541, 91496, '<td valign="top">I like the weird viewpoint/angles going on in this image.  However the reflections and tilt just sort of make it seems more cluttered than artistic.</td>', 'I like the weird viewpoint/angles going on in this image.  However the reflections and tilt just sort of make it seems more cluttered than artistic.', '2010-03-27 19:11:31.000000', NULL, 1),
(5919300, 862079, 91496, '<td valign="top">Very interesting angle here.  The reflections and the washed out top area are somewhat distracting.</td>', 'Very interesting angle here.  The reflections and the washed out top area are somewhat distracting.', '2010-03-27 19:12:21.000000', NULL, 1),
(5919301, 862306, 91496, '<td valign="top">As a abstract and a play on light and dark this image is superb. However as a PT&amp;A photo I do not see what you were going for.</td>', 'As a abstract and a play on light and dark this image is superb. However as a PT&A photo I do not see what you were going for.', '2010-03-27 19:15:03.000000', NULL, 1),
(5919302, 862470, 91496, '<td valign="top">I like the composition on this one with the bus, marina, and mountains.  Think a wider crop which removed much of the sky would have been more powerful.  The image all looks a little pixelated or noisy.</td>', 'I like the composition on this one with the bus, marina, and mountains.  Think a wider crop which removed much of the sky would have been more powerful.  The image all looks a little pixelated or noisy.', '2010-03-27 19:17:36.000000', NULL, 1),
(5919303, 862576, 91496, '<td valign="top">I like the sepia toning on the steamer, but the pink tones on the vegetation I like a lot less.<br/><br/><i>Message edited by author 2010-03-31 17:01:01.</i></td>', 'I like the sepia toning on the steamer, but the pink tones on the vegetation I like a lot less.', '2010-03-27 19:19:16.000000', '2010-03-31 18:01:01.000000', 1),
(5919305, 861983, 91496, '<td valign="top">Nice panning here.  I really like the sharpness on the driver and the blur on the racer.  Not really an automobile however.</td>', 'Nice panning here.  I really like the sharpness on the driver and the blur on the racer.  Not really an automobile however.', '2010-03-27 19:20:51.000000', NULL, 1),
