(5921980, 861575, 46918, '<td valign="top">A sad end to a wonderful bus. I like the b&amp;w</td>', 'A sad end to a wonderful bus. I like the b&w', '2010-03-29 23:49:35.000000', NULL, 1),
(5921981, 861658, 46918, '<td valign="top">Great Idea for a shot. The cars do look like toys. At first I thought you had dome some "extreme" editing but I caught it before I graded....Good job.</td>', 'Great Idea for a shot. The cars do look like toys. At first I thought you had dome some "extreme" editing but I caught it before I graded....Good job.', '2010-03-29 23:53:19.000000', NULL, 1),
(5922080, 861948, 63503, '<td valign="top">Very nice !! I suspect it would look even better with a bit of shadows and highlites (legal in basic) to darken the sky and provide more detail to the lower part of the car. Beautiful car, beautiful picture.</td>', 'Very nice !! I suspect it would look even better with a bit of shadows and highlites (legal in basic) to darken the sky and provide more detail to the lower part of the car. Beautiful car, beautiful picture.', '2010-03-30 02:17:09.000000', NULL, 1),
(5922082, 862529, 63503, '<td valign="top">Very nice job balancing the outside and inside exposures.</td>', 'Very nice job balancing the outside and inside exposures.', '2010-03-30 02:18:33.000000', NULL, 1),
(5922087, 862565, 63503, '<td valign="top">This is a great story teller and a beautiful truck! it is too bad that you couldn''t achieve a focus point. I don''t think that the whole image needed to be in focus but in general I think photographs look better when a key element is in focus. (no vote)</td>', 'This is a great story teller and a beautiful truck! it is too bad that you couldn''t achieve a focus point. I don''t think that the whole image needed to be in focus but in general I think photographs look better when a key element is in focus. (no vote)', '2010-03-30 02:22:05.000000', NULL, 1),
(5922088, 862652, 63503, '<td valign="top">Great use of perspective and leading lines !!</td>', 'Great use of perspective and leading lines !!', '2010-03-30 02:23:05.000000', NULL, 1),
(5922092, 862214, 63503, '<td valign="top">Oh my! I hope the bullets came after and not before the demise of this truck. Good capture considering the extremely harsh light. I looks like a place worth returnig to for a picture at sunset or sunrise.</td>', 'Oh my! I hope the bullets came after and not before the demise of this truck. Good capture considering the extremely harsh light. I looks like a place worth returnig to for a picture at sunset or sunrise.', '2010-03-30 02:31:57.000000', NULL, 1),
(5922093, 862461, 63503, '<td valign="top">Nice symetry here.</td>', 'Nice symetry here.', '2010-03-30 02:34:23.000000', NULL, 1),
(5922094, 861983, 63503, '<td valign="top">Very nice panning !!</td>', 'Very nice panning !!', '2010-03-30 02:35:34.000000', NULL, 1),
(5922095, 862545, 63503, '<td valign="top">This is my favorite type of car photography, I can''t wait to find out where you placed you camera and how you triggered it. Your location is fantastic and your choices of shutter speed and f-stop are perfect. High marks from me.</td>', 'This is my favorite type of car photography, I can''t wait to find out where you placed you camera and how you triggered it. Your location is fantastic and your choices of shutter speed and f-stop are perfect. High marks from me.', '2010-03-30 02:42:00.000000', NULL, 1),
(5922096, 862114, 63503, '<td valign="top">Very nicely panned, amazing focus on the moving vehicle. I wonder if a non-centered composition would have looked even better?</td>', 'Very nicely panned, amazing focus on the moving vehicle. I wonder if a non-centered composition would have looked even better?', '2010-03-30 02:44:27.000000', NULL, 1),
(5922102, 862535, 63503, '<td valign="top">Holy cow !! You HAVE to tell me how you took this picture. I have been trying to figure out the way to safely mount a camera somewhere in the outside of a 182 in such a way that a portion of the aircraft is visisble in the frame (preferably without the obstructing wing) but have not come up with an answer yet. My dream is to take a long exposure (seveal seconds)picture during a take off (and/or landing), at dusk or night, from a busy airport with lights all over.</td>', 'Holy cow !! You HAVE to tell me how you took this picture. I have been trying to figure out the way to safely mount a camera somewhere in the outside of a 182 in such a way that a portion of the aircraft is visisble in the frame (preferably without the obstructing wing) but have not come up with an answer yet. My dream is to take a long exposure (seveal seconds)picture during a take off (and/or landing), at dusk or night, from a busy airport with lights all over.', '2010-03-30 02:55:23.000000', NULL, 1),
(5922103, 862313, 63503, '<td valign="top">Great picture!! where were you standing to take the picture!?! did they let you in the cockpit?</td>', 'Great picture!! where were you standing to take the picture!?! did they let you in the cockpit?', '2010-03-30 02:56:42.000000', NULL, 1);
