(5927250, 862535, 12796, '<td valign="top">such an excellent photo, but rules are rules. No exceptions. This being your 8th challenge, I presume you knew the rules, but still submitted an old photo. Sad.</td>', 'such an excellent photo, but rules are rules. No exceptions. This being your 8th challenge, I presume you knew the rules, but still submitted an old photo. Sad.', '2010-04-02 11:22:46.000000', NULL, 0),
(5927263, 862535, 69325, '<td valign="top"><table align="center" width="95%"><tr><td><div class="textsm"><b>Originally posted by amateurboi:</b></div><hr/><i> such an excellent photo, but rules are rules. No exceptions. This being your 8th challenge, I presume you knew the rules, but still submitted an old photo. Sad. </i></td></tr></table> <br/> <br/>whats really said is just assuming someone cheated, many people have had this happen simply because they forgot to make sure their camera was set to the right date.</td>', 'Originally posted by amateurboi: such an excellent photo, but rules are rules. No exceptions. This being your 8th challenge, I presume you knew the rules, but still submitted an old photo. Sad.   whats really said is just assuming someone cheated, many people have had this happen simply because they forgot to make sure their camera was set to the right date.', '2010-04-02 11:29:02.000000', NULL, 0),
(5927290, 862551, 12796, '<td valign="top">congratulations on your yellow. This was one of my highest votes.</td>', 'congratulations on your yellow. This was one of my highest votes.', '2010-04-02 11:41:54.000000', NULL, 0),
